<?php
 namespace Pterodactyl\Notifications\Dezerx; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Notifications\Messages\MailMessage; use Illuminate\Notifications\Notification; use Pterodactyl\Services\Dezerx\Emails; class StaffUpdate extends Notification implements ShouldQueue { use Queueable; public function __construct( private string $template, private array $values, private string $url = '', ) { } public function via(): array { return ['mail']; } public function toMail(): MailMessage { return Emails::apply(new MailMessage(), $this->template, $this->values, $this->url); } } 